45	void FDebugCameraManager::EnableDebugCamera(APlayerController* PlayerController)
46	{
47		if (PlayerController && PlayerController->Player && PlayerController->IsLocalPlayerController())
48		{
49			ADebugCameraController* DebugCameraController = nullptr;
50			if (FDebugCameraControllerStatus* DebugCameraControllerStatus = PlayerToDebugCameraControllerMap.Find(PlayerController->Player))
51			{
52				if (DebugCameraControllerStatus->bIsActive)
53				{
54					return;
55				}
56				DebugCameraController = DebugCameraControllerStatus->DebugCameraController;
57			}
58	
59			if (DebugCameraController == nullptr)
60			{
61				// spawn if necessary
62				FActorSpawnParameters SpawnInfo;
63				SpawnInfo.Instigator = PlayerController->GetInstigator();
64				DebugCameraController = PlayerController->GetWorld()->SpawnActor<ADebugCameraController>(DebugCameraControllerClass, SpawnInfo);
65				if (DebugCameraController != nullptr)
66				{
67					PlayerToDebugCameraControllerMap.Add(PlayerController->Player, FDebugCameraControllerStatus(DebugCameraController, false));
68				}
69			}
70	
71			if (ensure(DebugCameraController != nullptr))
72			{
73				PlayerToDebugCameraControllerMap[PlayerController->Player].bIsActive = true;
74	
75				// set up new controller
76				DebugCameraController->OnActivate(PlayerController);
77	
78				// then switch to it
79				PlayerController->Player->SwitchController(DebugCameraController);
80			}
81		}
82	}
