291		// If the view target is null, this is sort of a shortcut for "we're done with the current view target",
292		// so pop the context stack and reactivate the previous context.
293		if (NewViewTarget == nullptr)
294		{
295			ContextStack.PopContext();
296	
297			if (TSharedPtr<FCameraEvaluationContext> NewActiveContext = ContextStack.GetActiveContext())
298			{
299				if (UObject* NewActiveContextOwner = NewActiveContext->GetOwner())
300				{
301					NewViewTarget = Cast<AActor>(NewActiveContextOwner);
302					if (!NewViewTarget)
303					{
304						NewViewTarget = NewActiveContextOwner->GetTypedOuter<AActor>();
305					}
306				}
307			}
308		}
309	
310		// We pass empty transition params here because we never want to use PendingViewTarget, just ViewTarget.
311		Super::SetViewTarget(NewViewTarget, FViewTargetTransitionParams());
312	
313		if (!NewViewTarget)
314		{
315			return;
316		}
317	
318		// See if we can find the view target in the context stack. If so, reactivate it instead of potentially
319		// making a new context for the same thing.
320		TSharedPtr<FCameraEvaluationContext> ExistingContext = ContextStack.FindContextByPredicate(
321				[NewViewTarget](TSharedRef<FCameraEvaluationContext> Item)
322				{
323					UObject* Owner = Item->GetOwner();
324					return Owner && (Owner == NewViewTarget || Owner->GetTypedOuter<AActor>() == NewViewTarget);
325				});
326		if (ExistingContext)
327		{
328			// This will move the context to the top if it's already in the stack (which it is, we found it there).
329			ContextStack.PushContext(ExistingContext.ToSharedRef());
330		}
331		else
